package com.jjy.seorapjeongri;

import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import android.provider.Settings;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;

public class MainActivity extends Activity{
 final int PURPLE=Color.rgb(104,78,180),BG=Color.rgb(250,247,252),TEXT=Color.rgb(35,30,40); FrameLayout root; ExecutorService exec=Executors.newSingleThreadExecutor(); ArrayList<File> roots=new ArrayList<>();ArrayList<Item> items=new ArrayList<>();ArrayList<Result> results=new ArrayList<>();boolean all=false,paused=false;
 static class Item{File f;String cat,rel;boolean dup=true,checked=true;Item(File f,String c,String r){this.f=f;cat=c;rel=r;}} static class Result{String src,dst;boolean ok;Result(String s,String d,boolean o){src=s;dst=d;ok=o;}}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setNavigationBarColor(Color.WHITE);getWindow().setStatusBarColor(Color.WHITE);showHome();} protected void onDestroy(){exec.shutdownNow();super.onDestroy();}
 TextView tv(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(TEXT);return t;} Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(17);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundColor(PURPLE);return b;} LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(22,18,22,18);return l;}void base(){root=new FrameLayout(this);root.setBackgroundColor(BG);setContentView(root);}void add(LinearLayout l,View v,int h){l.addView(v,new LinearLayout.LayoutParams(-1,h));}
 void showHome(){base();LinearLayout l=col();l.setGravity(Gravity.CENTER_HORIZONTAL);root.addView(l,new FrameLayout.LayoutParams(-1,-1));Space a=new Space(this);l.addView(a,new LinearLayout.LayoutParams(1,0,1));TextView t=tv("서랍정리",38);t.setGravity(Gravity.CENTER);t.setTypeface(null,1);add(l,t,70);TextView s=tv("휴대폰 파일을 종류별로 깔끔하게 정리합니다.",17);s.setGravity(Gravity.CENTER);add(l,s,52);Button b=btn("파일 정리 시작");add(l,b,60);b.setOnClickListener(v->showArea());Space q=new Space(this);l.addView(q,new LinearLayout.LayoutParams(1,0,1));}
 void showArea(){base();LinearLayout l=col();root.addView(l,new FrameLayout.LayoutParams(-1,-1));TextView h=tv("정리할 영역을 선택하세요",29);h.setTypeface(null,1);add(l,h,55);add(l,tv("선택한 폴더와 하위 폴더를 검사합니다.",16),34);add(l,tv("JJY DATA는 자동 제외됩니다.",13),30);CheckBox ca=new CheckBox(this);ca.setText("전체 내부 저장소");ca.setTextSize(18);ca.setTextColor(TEXT);ca.setChecked(all);add(l,ca,54);ScrollView sv=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);File base=Environment.getExternalStorageDirectory();String[] names={"DCIM","Download","Pictures","Movies","Music","Documents"};ArrayList<CheckBox> boxes=new ArrayList<>();for(String n:names){File f=new File(base,n);if(f.isDirectory()){CheckBox c=new CheckBox(this);c.setText(n);c.setTextSize(18);c.setTextColor(TEXT);c.setChecked(roots.contains(f));list.addView(c,new LinearLayout.LayoutParams(-1,52));boxes.add(c);c.setOnCheckedChangeListener((x,on)->{if(on){if(!roots.contains(f))roots.add(f);}else roots.remove(f);});}}Button pick=new Button(this);pick.setText("기타 폴더 직접 선택");pick.setAllCaps(false);pick.setTextSize(17);list.addView(pick,new LinearLayout.LayoutParams(-1,54));pick.setOnClickListener(v->pickFolder());sv.addView(list);l.addView(sv,new LinearLayout.LayoutParams(-1,0,1));ca.setOnCheckedChangeListener((v,on)->{all=on;if(on){roots.clear();for(CheckBox x:boxes)x.setEnabled(false);}else for(CheckBox x:boxes)x.setEnabled(true);});Button next=btn("검사 시작");add(l,next,60);next.setOnClickListener(v->{if(all||!roots.isEmpty())access();else Toast.makeText(this,"정리할 영역을 하나 이상 선택하세요.",Toast.LENGTH_SHORT).show();});}
 void pickFolder(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,7);}public void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==7&&c==RESULT_OK&&d!=null)try{String id=DocumentsContract.getTreeDocumentId(d.getData());String[] p=id.split(":",2);if(p.length==2&&p[0].equalsIgnoreCase("primary")){File f=new File(Environment.getExternalStorageDirectory(),p[1]);if(f.isDirectory()&&!f.getName().equalsIgnoreCase("JJY DATA")&&!roots.contains(f))roots.add(f);Toast.makeText(this,f.getName()+" 폴더가 추가되었습니다.",Toast.LENGTH_SHORT).show();}}catch(Exception e){}}
 void access(){if(Build.VERSION.SDK_INT>=30&&!Environment.isExternalStorageManager()){startActivity(new Intent(Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION,Uri.parse("package:"+getPackageName())));Toast.makeText(this,"모든 파일 접근 권한을 허용한 뒤 앱으로 돌아오세요.",Toast.LENGTH_LONG).show();return;}scanScreen();}
 void scanScreen(){base();LinearLayout l=col();l.setGravity(Gravity.CENTER_HORIZONTAL);root.addView(l,new FrameLayout.LayoutParams(-1,-1));TextView h=tv("파일 검사",30);h.setTypeface(null,1);h.setGravity(Gravity.CENTER);add(l,h,60);TextView st=tv("검사 준비 중…",16);st.setGravity(Gravity.CENTER);add(l,st,50);ProgressBar p=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);add(l,p,18);exec.submit(()->{ArrayList<Item> found=scan(n->runOnUiThread(()->st.setText("검사 중: "+n)));runOnUiThread(()->{items=found;showPreview();});});}
 interface P{void go(String n);}ArrayList<Item> scan(P p){ArrayList<Item> out=new ArrayList<>();ArrayList<File> rs=new ArrayList<>();File b=Environment.getExternalStorageDirectory();if(all){File[] fs=b.listFiles();if(fs!=null)for(File f:fs)if(f.isDirectory()&&!f.getName().equalsIgnoreCase("JJY DATA")&&!f.getName().equalsIgnoreCase("Android"))rs.add(f);}else rs.addAll(roots);for(File r:rs)walk(r,"",out,p);HashMap<String,Integer> m=new HashMap<>();for(Item x:out){String k=x.f.getName().toLowerCase(Locale.ROOT)+"|"+x.f.length();m.put(k,m.getOrDefault(k,0)+1);}for(Item x:out)x.dup=m.get(x.f.getName().toLowerCase(Locale.ROOT)+"|"+x.f.length())>1;return out;}void walk(File d,String rel,ArrayList<Item> out,P p){if(!d.isDirectory()||d.getName().equalsIgnoreCase("JJY DATA"))return;File[] fs=d.listFiles();if(fs==null)return;for(File f:fs){if(f.getName().equalsIgnoreCase("JJY DATA"))continue;if(f.isDirectory())walk(f,rel.isEmpty()?f.getName():rel+"/"+f.getName(),out,p);else if(f.isFile()&&f.canRead()){String c=classify(f);if(c!=null){out.add(new Item(f,c,rel));p.go(f.getName());}}}}
 String classify(File f){String n=f.getName(),l=n.toLowerCase(Locale.ROOT),e=ext(l),b=base(l);if(e.equals("mp3"))return n.toUpperCase(Locale.ROOT).contains("MR")?"MR":"MP3";if(has(e,"jpg","jpeg","gif","png","tif","tiff","bmp","webp","heic","heif","avif"))return"IMAGE";if(e.equals("pdf"))return b.matches(".*(b[1-6]|[1-6]b|#[1-6]|[1-6]#|_c)$")?"악보":"PDF";if(has(e,"hwp","hwpx"))return"한글문서";if(has(e,"doc","docx","xls","xlsx","ppt","pptx","csv","rtf","odt","ods","odp"))return"MS문서";if(has(e,"zip","7z","rar","tar","gz","bz2","xz","tgz"))return"압축파일";if(has(e,"dwg","dwf","dxf","stp","step","igs","iges","ipt","iam","stl","obj","3ds","3mf","fbx","skp"))return"캐드파일";if(has(e,"avi","mp4","mkv","mov","wmv","flv","webm","m4v","3gp","mpeg","mpg","mts","m2ts","ts"))return"영상파일";return null;}boolean has(String e,String...a){for(String x:a)if(x.equals(e))return true;return false;}String ext(String s){int i=s.lastIndexOf('.');return i<0?"":s.substring(i+1);}String base(String s){int i=s.lastIndexOf('.');return i>0?s.substring(0,i):s;}
 void showPreview(){base();LinearLayout l=col();root.addView(l,new FrameLayout.LayoutParams(-1,-1));TextView h=tv("정리 미리보기",30);h.setTypeface(null,1);add(l,h,58);int d=0;for(Item x:items)if(x.dup)d++;add(l,tv("검사 완료  ·  대상 "+items.size()+"개  ·  중복 의심 "+d+"개",17),42);add(l,tv("체크 해제한 파일은 정리하지 않습니다.",14),38);Button list=btn("대상 파일 목록 / 체크박스");add(l,list,58);list.setOnClickListener(v->dialogItems());TextView info=tv("\n정리 규칙\nMP3 / MR / 이미지 / PDF / 악보 / 한글 / MS문서 / 압축 / CAD·3D / 영상\n\n같은 이름의 원본 폴더는 같은 목적지 폴더로 통합됩니다.\n파일명이 충돌하면 (1), (2), (3)…을 붙입니다.",15);l.addView(info,new LinearLayout.LayoutParams(-1,0,1));LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);Button back=btn("다시 선택"),go=btn("정리 실행");row.addView(back,new LinearLayout.LayoutParams(0,60,1));LinearLayout.LayoutParams gp=new LinearLayout.LayoutParams(0,60,1);gp.leftMargin=8;row.addView(go,gp);l.addView(row);back.setOnClickListener(v->showArea());go.setOnClickListener(v->{ArrayList<Item> c=new ArrayList<>();for(Item x:items)if(x.checked)c.add(x);if(c.isEmpty())Toast.makeText(this,"정리할 파일을 선택하세요.",Toast.LENGTH_SHORT).show();else move(c);});}
 void dialogItems(){LinearLayout wrap=new LinearLayout(this);wrap.setOrientation(LinearLayout.VERTICAL);CheckBox only=new CheckBox(this);only.setText("중복 의심만 보기");wrap.addView(only);ListView list=new ListView(this);wrap.addView(list,new LinearLayout.LayoutParams(-1,0,1));ArrayAdapter<String> ad=new ArrayAdapter<String>(this,android.R.layout.simple_list_item_multiple_choice){ArrayList<Item> vis(){ArrayList<Item> v=new ArrayList<>();for(Item x:items)if(!only.isChecked()||x.dup)v.add(x);return v;}public int getCount(){return vis().size();}public String getItem(int p){Item x=vis().get(p);return (x.checked?"☑ ":"☐ ")+x.f.getName()+"\n"+x.cat+" → JJY DATA/"+x.cat+(x.rel.isEmpty()?"":"/"+x.rel);}};list.setAdapter(ad);list.setChoiceMode(ListView.CHOICE_MODE_MULTIPLE);list.setOnItemClickListener((a,b,c,d)->{ArrayList<Item> v=ad.vis();v.get(c).checked=!v.get(c).checked;ad.notifyDataSetChanged();});only.setOnCheckedChangeListener((a,b)->ad.notifyDataSetChanged());AlertDialog dialog=new AlertDialog.Builder(this).setTitle("정리 대상 파일").setView(wrap).setNegativeButton("닫기",null).create();dialog.show();Window w=dialog.getWindow();if(w!=null)w.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.94),(int)(getResources().getDisplayMetrics().heightPixels*.80));}
 void move(ArrayList<Item> chosen){base();LinearLayout l=col();l.setGravity(Gravity.CENTER_HORIZONTAL);root.addView(l,new FrameLayout.LayoutParams(-1,-1));TextView h=tv("정리 실행",30);h.setTypeface(null,1);add(l,h,60);ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);add(l,bar,18);TextView st=tv("준비 중…",16);st.setGravity(Gravity.CENTER);add(l,st,48);Button pause=btn("일시중지");add(l,pause,58);pause.setOnClickListener(v->{paused=!paused;pause.setText(paused?"계속하기":"일시중지");});exec.submit(()->{ArrayList<Result> r=new ArrayList<>();for(int i=0;i<chosen.size();i++){while(paused)try{Thread.sleep(150);}catch(Exception e){}Item x=chosen.get(i);File d=destination(x);boolean ok=copyMove(x.f,d);r.add(new Result(x.f.getAbsolutePath(),d.getAbsolutePath(),ok));int n=i+1;runOnUiThread(()->{st.setText(n+" / "+chosen.size()+"  "+x.f.getName());bar.setProgress(n*100/chosen.size());});}runOnUiThread(()->{results=r;showDone();});});}
 File destination(Item x){File dir=new File(new File(Environment.getExternalStorageDirectory(),"JJY DATA"),x.cat);if(!x.rel.isEmpty())dir=new File(dir,x.rel);dir.mkdirs();File d=new File(dir,x.f.getName());if(!d.exists())return d;String n=x.f.getName();int k=n.lastIndexOf('.');String b=k>0?n.substring(0,k):n,e=k>0?n.substring(k):"";int i=1;do{d=new File(dir,b+" ("+i+++")"+e);}while(d.exists());return d;}boolean copyMove(File s,File d){try{FileInputStream in=new FileInputStream(s);FileOutputStream out=new FileOutputStream(d);byte[] buf=new byte[65536];int n;while((n=in.read(buf))>0)out.write(buf,0,n);in.close();out.close();return s.delete();}catch(Exception e){return false;}}
 void showDone(){base();LinearLayout l=col();root.addView(l,new FrameLayout.LayoutParams(-1,-1));TextView h=tv("정리 완료",30);h.setTypeface(null,1);add(l,h,60);int ok=0;for(Result r:results)if(r.ok)ok++;add(l,tv("처리 파일: "+results.size()+"개\n완료: "+ok+"개\n실패: "+(results.size()-ok)+"개",19),120);Button b=btn("정리 내역 보기");add(l,b,58);b.setOnClickListener(v->dialogResults());Space s=new Space(this);l.addView(s,new LinearLayout.LayoutParams(1,0,1));Button again=btn("처음으로");add(l,again,58);again.setOnClickListener(v->showHome());}void dialogResults(){StringBuilder s=new StringBuilder();for(Result r:results)s.append(r.ok?"완료  ":"실패  ").append(new File(r.src).getName()).append("\n→ ").append(r.dst).append("\n\n");TextView t=tv(s.toString(),13);ScrollView v=new ScrollView(this);v.addView(t);new AlertDialog.Builder(this).setTitle("정리 내역").setView(v).setNegativeButton("닫기",null).show();}
}
